    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceKeyProtector> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceKeyProtector>.allocate(capacity: 1)
