        /**
         * Turn the phone's physical screen off while mirroring (`session == 0`, Elevated).
         */screenOff: Bool, 
        /**
         * Only the sound, no picture: the PC plays it without a window.
         */soundOnly: Bool) {
        self.maxSize = maxSize
        self.fps = fps
        self.bitrate = bitrate
        self.audio = audio
        self.session = session
        self.app = app
