/**
 * A notification, as mirrored between devices
 * (docs/protocol/notifications.md).
 */
public struct Notification: Equatable, Hashable {
    /**
     * This device's ID for it (Android: the StatusBarNotification key).
     */
    public var key: String
    /**
     * Package name.
     */
    public var app: String
    public var appName: String
    public var title: String?
    public var text: String?
    public var sub: String?
    /**
     * Unix milliseconds.
     */
    public var when: Int64
    public var actions: [NotificationAction]
    /**
     * Arrived without sound or pop-up.
     */
    public var silent: Bool
    /**
     * The app icon as PNG; pass it every time, the core sends it once per
     * device and connection.
     */
    public var icon: Data?
    /**
     * A picture it shows (a photo in a message, a big picture): JPEG, at
     * most 160 KiB.
     */
    public var image: Data?
    /**
     * Live Update / ongoing progress or timer metadata, when present.
     */
    public var live: NotificationLive?
    /**
     * Structured `MessagingStyle` conversation metadata, when present.
     */
    public var conversation: NotificationConversation?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * This device's ID for it (Android: the StatusBarNotification key).
         */key: String, 
        /**
         * Package name.
         */app: String, appName: String, title: String?, text: String?, sub: String?, 
        /**
         * Unix milliseconds.
         */when: Int64, actions: [NotificationAction], 
        /**
         * Arrived without sound or pop-up.
         */silent: Bool, 
        /**
         * The app icon as PNG; pass it every time, the core sends it once per
         * device and connection.
         */icon: Data?, 
        /**
         * A picture it shows (a photo in a message, a big picture): JPEG, at
         * most 160 KiB.
         */image: Data?, 
        /**
         * Live Update / ongoing progress or timer metadata, when present.
         */live: NotificationLive? = nil, 
        /**
         * Structured `MessagingStyle` conversation metadata, when present.
         */conversation: NotificationConversation? = nil) {
        self.key = key
        self.app = app
        self.appName = appName
        self.title = title
        self.text = text
        self.sub = sub
        self.when = when
        self.actions = actions
        self.silent = silent
        self.icon = icon
        self.image = image
        self.live = live
        self.conversation = conversation
    }

    

    
}

