/**
 * What a PC asked of a call.
 */

public enum CallCommand: Equatable, Hashable {
    
    case answer
    /**
     * Decline a ringing call, or hang up an active one.
     */
    case decline
    /**
     * Stop the ringing.
     */
    case silence
    /**
     * Mute (true) or unmute the microphone on the call.
     */
    case mute(on: Bool
    )
    /**
     * The speaker (true) or the earpiece.
     */
    case speaker(on: Bool
    )
    /**
     * Put the call on hold (true) or take it off.
     */
    case hold(on: Bool
    )
    /**
     * A keypad tone: "0"-"9", "*" or "#".
     */
    case dtmf(digit: String
    )
    /**
     * The call's volume up (true) or down.
     */
    case volume(up: Bool
    )





}

#if compiler(>=6)
extension CallCommand: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCallCommand: FfiConverterRustBuffer {
    typealias SwiftType = CallCommand

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CallCommand {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .answer
        
        case 2: return .decline
        
        case 3: return .silence
        
        case 4: return .mute(on: try FfiConverterBool.read(from: &buf)
        )
        
        case 5: return .speaker(on: try FfiConverterBool.read(from: &buf)
        )
        
        case 6: return .hold(on: try FfiConverterBool.read(from: &buf)
        )
        
        case 7: return .dtmf(digit: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .volume(up: try FfiConverterBool.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CallCommand, into buf: inout [UInt8]) {
        switch value {
        
        
        case .answer:
            writeInt(&buf, Int32(1))
        
        
        case .decline:
            writeInt(&buf, Int32(2))
        
        
        case .silence:
            writeInt(&buf, Int32(3))
        
        
        case let .mute(on):
            writeInt(&buf, Int32(4))
            FfiConverterBool.write(on, into: &buf)
            
        
        case let .speaker(on):
            writeInt(&buf, Int32(5))
            FfiConverterBool.write(on, into: &buf)
            
        
        case let .hold(on):
            writeInt(&buf, Int32(6))
            FfiConverterBool.write(on, into: &buf)
            
        
        case let .dtmf(digit):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(digit, into: &buf)
            
        
        case let .volume(up):
            writeInt(&buf, Int32(8))
            FfiConverterBool.write(up, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCallCommand_lift(_ buf: RustBuffer) throws -> CallCommand {
    return try FfiConverterTypeCallCommand.lift(buf)
}

