/**
 * Everything the UI needs to know about, as it happens.
 */

public enum Event: Equatable, Hashable {
    
    case deviceAdded(device: PairedDevice
    )
    case deviceRemoved(id: String
    )
    case linkChanged(id: String, link: Link
    )
    case peerInfoChanged(id: String, info: DeviceInfo
    )
    case peerPowerChanged(id: String, power: PowerLevel
    )
    case battery(id: String, battery: Battery
    )
    /**
     * A device asked this one to start (or stop) ringing.
     */
    case ring(id: String, on: Bool
    )
    case discovered(device: DiscoveredDevice
    )
    case discoveryExpired(id: String
    )
    /**
     * Show this 6-digit code and ask the user whether it matches.
     */
    case pairingCode(peer: String, code: String
    )
    case paired(device: PairedDevice
    )
    case pairingFailed(failure: PairingFailure
    )
    case capabilities(id: String, features: [Feature]
    )
    case notificationsReset(id: String, items: [Notification]
    )
    case notificationPosted(id: String, notification: Notification
    )
    case notificationRemoved(id: String, key: String
    )
    /**
     * A device put text on this phone's clipboard.
     */
    case clipboardReceived(id: String
    )
    /**
     * The local clipboard history changed.
     */
    case clipboardHistoryChanged
    /**
     * A file transfer started, progressed or finished.
     */
    case transfer(transfer: Transfer
    )
    /**
     * A device's media players (all of them; empty when nothing plays
     * there, or media is off for it).
     */
    case mediaChanged(id: String, players: [MediaPlayer]
    )
    /**
     * A paired phone took a photo (PCs only; phones announce theirs).
     */
    case photoAdded(id: String, photoId: String
    )
    /**
     * A call on a paired phone changed (PCs only; phones report theirs).
     */
    case callChanged(id: String, callId: String
    )
    /**
     * A paired phone's call history changed (PCs only).
     */
    case callLogChanged(id: String
    )
    /**
     * A paired phone's contacts changed (PCs only).
     */
    case contactsChanged(id: String
    )
    /**
     * A paired phone's screen (session 0) or app window started or
     * stopped showing (PCs only).
     */
    case mirroring(id: String, session: UInt32, on: Bool
    )
    /**
     * A paired phone's messages changed (PCs only).
     */
    case smsChanged(id: String, thread: String?
    )
    /**
     * A paired phone's photo library changed (PCs only).
     */
    case photosChanged(id: String
    )
    /**
     * A paired phone asked to control this PC while `remote_input` is off
     * (PCs only).
     */
    case remoteInputRequested(id: String
    )
    /**
     * A paired phone's quick settings state (PCs only).
     */
    case phoneToggles(id: String, toggles: PhoneToggles
    )
    /**
     * A paired PC's stored Wake-on-LAN addresses changed (phones only).
     */
    case wakeInfoChanged(id: String, canWake: Bool
    )
    /**
     * Reconnecting to a paired device by itself was turned off or back on
     * (`set_reconnect`).
     */
    case reconnectChanged(id: String, on: Bool
