public enum FeatureStatus: Equatable, Hashable {
    
    case available
    case partial(limit: String, upgrade: Upgrade?
    )
    case locked(upgrade: Upgrade
    )
    /**
     * `reason`: "deviceKinds", "android:<release>", "windows:<build>" or
     * "notOnThisDevice".
     */
    case unsupported(reason: String
    )





}

#if compiler(>=6)
extension FeatureStatus: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFeatureStatus: FfiConverterRustBuffer {
    typealias SwiftType = FeatureStatus

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FeatureStatus {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .available
        
        case 2: return .partial(limit: try FfiConverterString.read(from: &buf), upgrade: try FfiConverterOptionTypeUpgrade.read(from: &buf)
        )
        
        case 3: return .locked(upgrade: try FfiConverterTypeUpgrade.read(from: &buf)
        )
        
        case 4: return .unsupported(reason: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FeatureStatus, into buf: inout [UInt8]) {
        switch value {
        
        
        case .available:
            writeInt(&buf, Int32(1))
        
        
        case let .partial(limit,upgrade):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(limit, into: &buf)
            FfiConverterOptionTypeUpgrade.write(upgrade, into: &buf)
            
        
        case let .locked(upgrade):
            writeInt(&buf, Int32(3))
            FfiConverterTypeUpgrade.write(upgrade, into: &buf)
            
        
        case let .unsupported(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


