/**
 * Why a phone storage operation failed (`docs/protocol/storage.md`).
 */
public 
enum StorageFailure: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case NotFound
    case Denied
    case Invalid(reason: String
    )
    case NoSpace
    case Unsupported
    case Failed(reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension StorageFailure: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeStorageFailure: FfiConverterRustBuffer {
    typealias SwiftType = StorageFailure

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> StorageFailure {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotFound
        case 2: return .Denied
        case 3: return .Invalid(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .NoSpace
        case 5: return .Unsupported
        case 6: return .Failed(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: StorageFailure, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .NotFound:
            writeInt(&buf, Int32(1))
        
        
        case .Denied:
            writeInt(&buf, Int32(2))
        
        
        case let .Invalid(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .NoSpace:
            writeInt(&buf, Int32(4))
        
        
        case .Unsupported:
            writeInt(&buf, Int32(5))
        
        
        case let .Failed(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
