public enum TransferStatus: Equatable, Hashable {
    
    /**
     * Incoming transfer waiting for the user to accept or decline (LocalSend).
     */
    case requested
    /**
     * Waiting for the other device (to connect, or to continue).
     */
    case waiting
    case running
    /**
     * Manually paused by either side; partial files are kept on the receiver.
     */
    case paused
    /**
     * `saved`: where received files are, one path per item in `names`:
     * each file, and each sent folder (empty when
     * sending).
     */
    case done(saved: [String]
    )
    /**
     * `reason`: "denied", "unreachable", "noSpace", "interrupted", "integrity"
     * or "other".
     */
    case failed(reason: String
    )
    case cancelled





}

#if compiler(>=6)
extension TransferStatus: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTransferStatus: FfiConverterRustBuffer {
    typealias SwiftType = TransferStatus

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TransferStatus {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .requested
        
        case 2: return .waiting
        
        case 3: return .running
        
        case 4: return .paused
        
        case 5: return .done(saved: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 6: return .failed(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .cancelled
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TransferStatus, into buf: inout [UInt8]) {
        switch value {
        
        
        case .requested:
            writeInt(&buf, Int32(1))
        
        
        case .waiting:
            writeInt(&buf, Int32(2))
        
        
        case .running:
            writeInt(&buf, Int32(3))
        
        
        case .paused:
            writeInt(&buf, Int32(4))
        
        
        case let .done(saved):
            writeInt(&buf, Int32(5))
            FfiConverterSequenceString.write(saved, into: &buf)
            
        
        case let .failed(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .cancelled:
            writeInt(&buf, Int32(7))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeTransferStatus_lift(_ buf: RustBuffer) throws -> TransferStatus {
    return try FfiConverterTypeTransferStatus.lift(buf)
}

